css_snippet:
/* Refine link underlines for superior UI aesthetics */
a {
  text-decoration: underline; /* Ensure underline is present */
  text-decoration-color: var(--link-color, #007bff); /* Custom color */
  text-decoration-thickness: 0.08em; /* Thinner line, relative to font-size */
  text-underline-offset: 0.2em; /* Lift the underline slightly from descenders */
}

/* Apply to emphasized text or headings for consistency */
h2.emphasized span {
  text-decoration: underline;
  text-decoration-thickness: 0.06em; /* Even finer for larger text */
  text-underline-offset: 0.15em;
  text-decoration-style: solid; /* Or 'wavy', 'double', 'dotted', 'dashed' */
}
